package gateway

import "html/template"

var page = template.Must(template.New("page").Parse(`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>mcp-gateway · Activity</title><style>
:root{font-family:system-ui,sans-serif;color:#172b26;background:#f6f7f3}*{box-sizing:border-box}body{margin:0}header{background:#153e32;color:#fff;padding:22px max(24px,calc((100vw - 1100px)/2));display:flex;align-items:center;justify-content:space-between;gap:16px}header a{color:white;text-decoration:none;font-size:20px;font-weight:750}header small{color:#c3d7cc}main{max-width:1100px;margin:40px auto;padding:0 24px 60px}h1{font-size:32px;letter-spacing:-1px;margin-bottom:8px}h2{font-size:20px;margin-top:32px}.sub{color:#586b62;margin-top:0;line-height:1.6}.card{background:white;border:1px solid #dbe1d9;border-radius:12px;padding:24px;margin:16px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px}.grid .card{margin:0}a{color:#226a4d}button,.button{display:inline-block;border:1px solid #bccdc0;border-radius:6px;padding:10px 16px;background:white;color:#234b37;font:inherit;cursor:pointer;text-decoration:none}.primary{background:#216442;color:white;border-color:#216442}.danger{color:#9f3535}.actions{display:flex;gap:12px;margin-top:20px}form{margin:0}.badge{font:12px ui-monospace,monospace;border-radius:5px;padding:5px 8px;background:#eaf0e8;display:inline-block}.pending{background:#fff0c6;color:#77550b}.unknown,.denied,.failed{background:#fde9e5;color:#9c3724}.succeeded{background:#dff3e5;color:#175e37}table{border-collapse:collapse;width:100%;text-align:left;font-size:14px}td,th{padding:14px 10px;border-bottom:1px solid #e7ebe5}th{font-weight:500;color:#66756d;font-size:12px;text-transform:uppercase}code,pre{font-family:ui-monospace,monospace;font-size:13px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f2f5ef;padding:20px;border-radius:8px}dl{display:grid;grid-template-columns:150px 1fr;gap:14px}dt{color:#647267}dd{margin:0;overflow-wrap:anywhere}.scroll{overflow-x:auto}.note{border-left:3px solid #d4a740;padding:12px 16px;background:#fff9e9;font-size:14px;line-height:1.6}footer{font-size:12px;color:#6d786d;margin-top:32px}@media(max-width:600px){header{flex-wrap:wrap}main{margin-top:24px}.card{padding:16px}dl{grid-template-columns:1fr;gap:6px}dd{margin-bottom:10px}h1{font-size:27px}}
</style></head><body><header><a href="/">mcp-gateway</a><small>Single-owner preview · {{.Owner}}</small><form method="post" action="/logout"><button>Sign out</button></form></header><main>
{{with .Operation}}{{if .AmpThreadID}}<p class="note">Requested by Amp user <code>{{.AmpUserID}}</code> · <a href="https://ampcode.com/threads/{{.AmpThreadID}}">Open Amp thread</a><br>Identity verified by Amp. This is not human approval or model attestation.</p>{{end}}{{end}}
{{if .Operation}}{{with .Operation}}<a href="/">← All activity</a><h1>{{.Tool}}</h1><p class="sub">Exact request review · <code>{{.ID}}</code></p><div class="card"><span class="badge {{.Status}}">{{.Status}}</span><dl><dt>On behalf of</dt><dd>{{.Subject}}</dd><dt>Connection</dt><dd>{{.Connection}}</dd><dt>Upstream account</dt><dd>{{.Account}} <small>(configured label)</small></dd><dt>Calling model</dt><dd>{{if .Model}}{{.Model}} — client-reported, unverified{{else}}Unknown — not supplied by client{{end}}</dd><dt>Request digest</dt><dd><code>{{.Digest}}</code></dd></dl><h2>Exact arguments</h2><pre>{{$.Arguments}}</pre>{{if eq .Status "pending"}}<p class="note">Approve only if the account, tool and arguments are correct. Approval expires 10 minutes after submission and authorises this stored request once. This is not an effect preview.</p><div class="actions"><form method="post" action="/operations/{{.ID}}/approve"><button class="primary">Approve once</button></form><form method="post" action="/operations/{{.ID}}/deny"><button class="danger">Deny</button></form></div>{{else}}<p class="sub">Refresh to see the latest durable execution status.</p><a class="button" href="/operations/{{.ID}}">Refresh status</a>{{end}}{{if .Result}}<h2>Upstream result</h2><pre>{{printf "%s" .Result}}</pre>{{end}}</div>{{end}}
{{else}}<h1>Tools with a clear permission boundary.</h1><p class="sub">Connect once. Review consequential calls. Keep a record of every execution.</p><h2>Connections</h2><div class="grid">{{range .Connections}}<div class="card"><strong>{{.ID}}</strong><p class="sub">{{.Account}}</p>{{if .OAuth}}<a class="button" href="/connections/{{.ID}}/connect">Connect / reconnect OAuth</a>{{else}}<span class="badge">Environment bearer token</span>{{end}}</div>{{end}}</div><h2>Operations</h2><div class="card scroll">{{if .Operations}}<table><thead><tr><th>Request</th><th>Tool</th><th>Account</th><th>Status</th></tr></thead><tbody>{{range .Operations}}<tr><td><a href="/operations/{{.ID}}">{{.ID}}</a></td><td>{{.Tool}}</td><td>{{.Account}}</td><td><span class="badge {{.Status}}">{{.Status}}</span></td></tr>{{end}}</tbody></table>{{else}}<p class="sub">No operations yet. Connect an MCP client and use find_tools, then call_tools.</p>{{end}}</div><h2>Audit trail</h2><div class="card scroll"><table><thead><tr><th>Sequence</th><th>Operation</th><th>Transition</th><th>Actor</th></tr></thead><tbody>{{range .Events}}<tr><td>{{.Sequence}}</td><td><a href="/operations/{{.Operation}}">{{.Operation}}</a></td><td>{{.Kind}}</td><td>{{.Actor}}</td></tr>{{else}}<tr><td colspan="4">No events yet.</td></tr>{{end}}</tbody></table></div>{{end}}<footer>Local durable audit · encrypted payloads · not independently tamper-proof · no automatic write retries</footer></main></body></html>`))
